mapper.select:
SELECT T2.* FROM (SELECT T1.PRD_DESIGN_ID AS PRD_DESIGN_ID, T1.MOCK_DATE AS MOCK_DATE, T1.BATCH_ID AS BATCH_ID FROM MOCK_RESULT_INFO T1 where 1=1
AND T1.PRD_DESIGN_ID = #{prdDesignId}
AND T1.GENERATE_TIME = (SELECT MAX(A.GENERATE_TIME) FROM MOCK_RESULT_INFO A WHERE A.PRD_DESIGN_ID = T1.PRD_DESIGN_ID AND A.MOCK_DATE = T1.MOCK_DATE)) TEMP LEFT JOIN MOCK_TRADE_DEAL T2 ON TEMP.PRD_DESIGN_ID = T2.PRD_DESIGN_ID AND TEMP.MOCK_DATE = T2.TRADE_DATE AND trim(TEMP.BATCH_ID) = T2.BATCH_ID

select T2.PRD_DESIGN_SERIAL_NAME finProductName
from PRODUCT_DESIGN_INFO T2


		AND T2.PRD_DESIGN_ID = #{prdDesignId}

select t.PRD_DESIGN_ID id,t.PRD_DESIGN_SERIAL_NAME text,t.PRD_DESIGN_ID object from PRODUCT_DESIGN_INFO t


		AND T.DATA_STATUS = #{dataStatus}


	AND t.PRD_DESIGN_SERIAL_NAME like concat('%',concat(#{search},'%'))
